function i(e){switch(e.type){case"heading":return e.text;case"paragraph":return e.text;case"list":return e.items.join(" ");case"quote":return e.text;case"callout":return e.text;case"image":return e.caption??"";case"diagram":return e.caption??"";case"cta-tool":case"internal-link":case"divider":return""}}function s(e){return e.reduce((t,n)=>t+i(n).split(/\s+/).filter(Boolean).length,0)}function c(e){return Math.max(1,Math.round(s(e)/200))}function o(e){return s(e)}function u(e){return e.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"")}function g(e){const t=new Map;return e.map(n=>{if(n.type!=="heading")return"";const r=u(n.text),a=(t.get(r)??0)+1;return t.set(r,a),a===1?r:`${r}-${a}`})}export{o as a,c as e,g as h,u as s};
